import{_ as l,l as s,o as t,c as o,v as d,p,x as r,d as n,i as E,S as B,b as e}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"冰山探测","description":"","frontmatter":{"title":"冰山探测","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/iceberg-detection.md","filePath":"quant/iceberg-detection.md","lastUpdated":1789023840000}'),h={name:"quant/iceberg-detection.md"};function c(m,a,u,A,q,b){const i=s("Mermaid");return t(),o("div",null,[a[1]||(a[1]=d('<h1 id="冰山探测" tabindex="-1">冰山探测 <a class="header-anchor" href="#冰山探测" aria-label="Permalink to &quot;冰山探测&quot;">​</a></h1><div class="epigraph"><p>显示深度不必等于可成交深度：冰山把总量拆成可见的峰值，其余藏在同一价位之后，公开簿上的人只能从成交与补量的路径去推断隐藏部分是否存在。</p><footer>—— 综合隐藏流动性与冰山订单的市场微观结构研究，对照 Harris 对展示数量的论述</footer></div><p><a href="/quant/order-types">订单类型</a> 一文把冰山写成指令接口：总量、峰值、隐藏余量。本篇写学术上如何<strong>从公开数据推断</strong>隐藏量曾经在场，对象是测量隐藏流动性，不是设计诱单或干扰他人队列。Harris 强调展示是策略维度：把量大块挂在明处会泄露意向，隐藏则牺牲被其他限价发现的机会。Bessembinder、Panayides、Venkataraman 等把隐藏流动性当成市场质量的一部分——部分成交发生在显示深度之外。探测算法要回答的是：哪些成交路径与「峰值耗尽后同价补量」相容，以及推断出的隐藏量如何进入冲击与不平衡的测量误差。不讨论伪造深度、立即撤销的展示手法；那些不是冰山的学术定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>L2 快照只给出各价位聚合显示量。冰山的隐藏部分不在这个数字里，直到它被提升为新的峰值或被主动单撞上。于是出现两类误测：存量不平衡把卖侧读得过薄，因为隐藏卖量没显示；有效深度把可吃的量估低，主动单的预期冲击估高。没有一种合法的公开馈送会把对手的隐藏余量写成字段给你——那会取消隐藏的意义。问题是用成交与随后的显示量路径做<strong>统计推断</strong>：在何种事件序列下，隐藏余量比「恰好有人同时新挂一张同价单」更像数据生成过程。</p><p>识别永远不完美。同价位上本来就可以有多张独立限价单；一张显示单成交后，后面的显示单会露出来，看起来也像补量。学术探测给出的是候选集与概率，不是交易所里的冰山标志。把候选当成确定的对手隐藏单去交易，既超出识别集，也不属于本文。</p><h3 id="峰值耗尽与同价刷新" tabindex="-1">峰值耗尽与同价刷新 <a class="header-anchor" href="#峰值耗尽与同价刷新" aria-label="Permalink to &quot;峰值耗尽与同价刷新&quot;">​</a></h3><p>交易所冰山的典型机制是：显示峰值 \\(q_{\\mathrm{peak}}\\) 被吃完后，若隐藏余量仍为正，系统在同一价格生成一张新的显示单（有的市场重新排队，有的保留某种优先）。公开数据里的签名是：在价格 \\(p\\) 上出现一笔（或一串）成交，显示量降到接近零，随后极短时间内同一价位显示量回到约 \\(q_{\\mathrm{peak}}\\) 的水平，且中间没有可见的价格改善把该档打穿。这与「有人另行提交一张新限价单」在时间分辨率足够高时仍可能无法逐笔区分，但刷新延迟的分布、峰值大小的重复出现，会让冰山假设的似然上升。</p><p><span class="marginnote">成交量大于当时显示量，是隐藏流动性的另一条硬签名：主动单在该价吃掉的量超过快照上的 \\(q\\)，差额来自隐藏或来自快照间隔内的增单。快照稀疏时这条规则会把间隔内的普通加单误判为隐藏，必须用事件馈送。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据最低要求是带时间戳的成交与 BBO（或 L2）事件，最好是 L3 显示单编号。算法上常用规则集，而不是单一不等式：</p><ol><li><strong>超量成交</strong>。成交发生时，该价位成交量 $v\\gt $ 显示量 \\(q_{\\mathrm{disp}}\\)（或 \\(v\\gt q_{\\mathrm{disp}}+\\epsilon\\) 以吸收时间戳错位），标记隐藏执行。</li><li><strong>同价刷新</strong>。显示量在成交后降至阈值以下，在 \\(\\Delta t\\) 内于同一价格恢复到接近成交前峰值的水平，且 BBO 未向不利方向穿过该价。</li><li><strong>峰值重复</strong>。同一价位上多次出现几乎相同的显示量台阶，像系统生成的固定峰值，而不是人工随意改量。</li></ol><p>规则 1 测的是隐藏量被执行，规则 2–3 测的是冰山式的展示机制。没有交易所标志时，应报告候选率、并用随机的「成交后同价新挂」作为对照强度：若对照已经很高，探测的精确度有限。Frey 与 Sandås 等结构方法把隐藏与显示的提交写成强度，用似然估计隐藏比例，比纯规则更贵，但对「恰好同时新挂」有更明确的原假设。</p><h3 id="探测结果怎样进入其他度量" tabindex="-1">探测结果怎样进入其他度量 <a class="header-anchor" href="#探测结果怎样进入其他度量" aria-label="Permalink to &quot;探测结果怎样进入其他度量&quot;">​</a></h3><p>得到候选隐藏执行之后，可以构造「调整后深度」：显示量加上推断的隐藏余量（余量往往不可点估计，只能给下界，即已执行的超量）。<a href="/quant/ofi-cont">OFI</a> 若只用显示 \\(\\Delta q\\)，会在隐藏成交时低估供给变化；把超量成交补进 \\(e^A\\) 或 \\(e^B\\)，冲击回归的 \\(\\beta\\) 会变。存量不平衡在冰山密集的一侧会持续偏斜，短窗预测力里有一块是测量误差而不是意向。研究应报告「仅显示」与「显示+隐藏下界」两套不平衡，而不是把探测做成交易信号后再回测 alpha。</p><p>寿命统计也要分开：冰山的显示峰值可以短，隐藏余量的寿命长。把峰值的撤单算进<a href="/quant/cancel-rate">撤单速率</a> 没有错，但解释应改为「显示层修订」，不要说整张意向都被收回。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>隐藏的动机是减少展示：大买意向若全部出现在买档，会招来抢跑与更差的后续价格，也会让卖方抬价。冰山在公开簿上维持一个小峰值，既还能排队等待被动成交，又把总量的大部分从竞争对手的眼睛里拿掉。代价是：其他提供方按显示深度做决策，可能在「其实还有隐藏卖」的价位上过度主动买入，或者误以为该档已空而撤走。信息不对称多了一层：<strong>真实可成交量在哪</strong> 对部分参与者不可见。O&#39;Hara 框架里的信息不仅是关于价值，也可以是关于簿。</p><p>探测算法利用的是撮合与展示规则留下的路径约束，不是去还原下单者身份。刷新延迟由交易所系统决定，往往短于人工重新键入一张同价单。这是识别的来源，也是边界：若市场允许完全隐藏（不显示峰值）或暗池成交，公开簿路径上可能没有任何刷新，规则 2 失效，只剩规则 1 在主市场成交里抓超量。</p><h3 id="与暗池、完全隐藏的边界" tabindex="-1">与暗池、完全隐藏的边界 <a class="header-anchor" href="#与暗池、完全隐藏的边界" aria-label="Permalink to &quot;与暗池、完全隐藏的边界&quot;">​</a></h3><p>冰山仍在公开簿的价格网格上排队，价格是可见的，数量部分可见。暗池匹配通常不预先展示价格与深度，成交事后报告，公开 OFI 根本看不见那笔需求。学术上两者都叫隐藏流动性，探测方法不能共用：暗池依赖成交报告与公开簿消耗的对照，冰山依赖同价显示路径。把所有「显示量解释不了的成交」叫做冰山，会把暗池、延迟加单、数据缺口混成一类，隐藏比例被高估。</p><p><span class="marginnote">本文的探测是测量：隐藏执行的频率、对深度与冲击度量的修正。它不提供如何伪装峰值、如何干扰他人推断的任何步骤。识别集停在公开事件序列与交易所展示规则。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>快照间隔大于刷新延迟时，规则 2 看不见峰值恢复，只能靠规则 1，且规则 1 被间隔内加单污染。多市场同一价位的显示量不能简单相加再比成交：成交在一处发生，显示在另一处。涨跌停板上的「成交后量又出现」常常是排队机制，不是冰山。不要用探测候选去构建「抓冰山」的交易策略再声称学术复制——那超出测量目的，也把高错误率的分类当成 alpha。</p><p>不要把冰山探测写成<a href="/quant/cancel-rate">撤单速率</a> 的阈值规则，也不要把它与诱骗式展示-撤销混名。冰山的学术对象是合法的部分展示指令及其可观测签名。与 <a href="/quant/l2-l3-data">L2/L3</a> 对照：没有订单编号时，同价刷新无法确认是同一张逻辑单的峰值，精确度下降，应只报告下界与敏感性。</p><p><span class="marginnote">隐藏流动性的经验研究包括 Bessembinder, Panayides &amp; Venkataraman 等对 hidden liquidity 的讨论；冰山展示机制见各交易所规则与 Harris 对 display quantity 的论述。结构估计见 Frey、Sandås 一类订单提交模型。不要把监管上的滥用案例写进冰山定义。</span></p>',26)),(t(),p(B,null,{default:r(()=>[E(i,{id:"mermaid-90",class:"mermaid",graph:"flowchart%20TD%0A%20%20DISP%5B%22%E6%98%BE%E7%A4%BA%E6%B7%B1%E5%BA%A6%20q%22%5D%20--%3E%20TR%5B%22%E8%AF%A5%E4%BB%B7%E6%88%90%E4%BA%A4%20v%22%5D%0A%20%20TR%20--%3E%7C%22v%20%3E%20q%22%7C%20HID%5B%22%E9%9A%90%E8%97%8F%E6%89%A7%E8%A1%8C%EF%BC%88%E4%B8%8B%E7%95%8C%EF%BC%89%22%5D%0A%20%20TR%20--%3E%7C%22%E5%B3%B0%E5%80%BC%E8%80%97%E5%B0%BD%22%7C%20RF%5B%22%CE%94t%20%E5%86%85%E5%90%8C%E4%BB%B7%E6%98%BE%E7%A4%BA%E6%81%A2%E5%A4%8D%22%5D%0A%20%20RF%20--%3E%20ICE%5B%22%E5%86%B0%E5%B1%B1%E5%BC%8F%E5%88%B7%E6%96%B0%E5%80%99%E9%80%89%22%5D%0A%20%20HID%20--%3E%20ADJ%5B%22%E8%B0%83%E6%95%B4%E6%B7%B1%E5%BA%A6%20%2F%20%E4%BF%AE%E6%AD%A3%20OFI%22%5D%0A%20%20ICE%20--%3E%20ADJ%0A%20%20DARK%5B%22%E6%9A%97%E6%B1%A0%E6%88%90%E4%BA%A4%22%5D%20-.-%3E%7C%22%E6%97%A0%E5%85%AC%E5%BC%80%E5%88%B7%E6%96%B0%22%7C%20RF%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[n("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"冰山探测从公开成交与显示路径推断隐藏流动性：超量成交、同价刷新、峰值重复，给出候选而非交易所标志。"),e("li",null,"目的是修正深度、不平衡与冲击的测量误差，不是还原对手策略。"),e("li",null,"快照过疏、多市场、暗池会使规则失效或把不同隐藏形式混在一起。"),e("li",null,"与完全隐藏、暗池、显示层撤单速率是不同对象；不涉及伪造深度的展示手法。"),e("li",null,"出处：Harris 对展示数量的论述；Bessembinder 等隐藏流动性研究；订单提交结构模型见 Frey–Sandås 等。")],-1))])}const C=l(h,[["render",c]]);export{g as __pageData,C as default};
